// Flaw 1: No constructor declared -> compiler provides public no-arg constructor!
// Flaw 2: Making it abstract allows clients to subclass and instantiate it anyway.
public abstract class StringUtils {
    public static boolean isEmpty(String s) {
        return s == null || s.trim().isEmpty();
    }
    // Subclasses can still instantiate this!
}

wrong_code.call_site:
public class Main {
    public static void main(String[] args) {
        // Unintended instantiation via subclass:
        class SubStringUtils extends StringUtils {}
        StringUtils utils = new SubStringUtils(); // Object created unnecessarily!
    }
}

right_code.class:
// Noninstantiable utility class
public final class StringUtils {
    // Suppress default constructor for noninstantiability
    private StringUtils() {
        throw new AssertionError("No StringUtils instances for you!");
    }

    public static boolean isEmpty(String s) {
        return s == null || s.trim().isEmpty();
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        // Clean, direct static invocation:
        boolean empty = StringUtils.isEmpty("  ");
        System.out.println(empty); // true

        // new StringUtils(); // Compile-time error: private constructor!
    }
}
